-- PostgreSQL production foundation for Honey Vision commerce.
CREATE TABLE users (id UUID PRIMARY KEY, phone VARCHAR(20) UNIQUE NOT NULL, name TEXT, email TEXT, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE products (id UUID PRIMARY KEY, slug TEXT UNIQUE NOT NULL, name TEXT NOT NULL, brand TEXT, category TEXT, price_paise INTEGER NOT NULL, mrp_paise INTEGER, stock INTEGER NOT NULL DEFAULT 0, active BOOLEAN NOT NULL DEFAULT true, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE addresses (id UUID PRIMARY KEY, user_id UUID NOT NULL REFERENCES users(id), name TEXT NOT NULL, phone VARCHAR(20) NOT NULL, line1 TEXT NOT NULL, city TEXT NOT NULL, pin VARCHAR(6) NOT NULL);
CREATE TABLE orders (id UUID PRIMARY KEY, order_number TEXT UNIQUE NOT NULL, user_id UUID REFERENCES users(id), address_id UUID REFERENCES addresses(id), status TEXT NOT NULL, payment_status TEXT NOT NULL, payment_method TEXT NOT NULL, subtotal_paise INTEGER NOT NULL, shipping_paise INTEGER NOT NULL, installation_paise INTEGER NOT NULL DEFAULT 0, total_paise INTEGER NOT NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE order_items (id UUID PRIMARY KEY, order_id UUID NOT NULL REFERENCES orders(id), product_id UUID NOT NULL REFERENCES products(id), quantity INTEGER NOT NULL CHECK (quantity > 0), unit_price_paise INTEGER NOT NULL, installation_requested BOOLEAN NOT NULL DEFAULT false);
CREATE TABLE installation_bookings (id UUID PRIMARY KEY, order_id UUID NOT NULL REFERENCES orders(id), slot_start TIMESTAMPTZ, slot_end TIMESTAMPTZ, status TEXT NOT NULL DEFAULT 'requested', technician_id UUID, notes TEXT);
CREATE TABLE payment_events (id UUID PRIMARY KEY, order_id UUID NOT NULL REFERENCES orders(id), provider TEXT NOT NULL, provider_payment_id TEXT, event_type TEXT NOT NULL, verified BOOLEAN NOT NULL DEFAULT false, payload JSONB, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
